package it.polimi.ingsoft.mesos.server.controller.command;

import it.polimi.ingsoft.mesos.server.virtualview.Listener;

/**
 * Internal queue command used when an existing session disconnects.
 *
 * <p>This command is generated by server lifecycle code, not by a client
 * payload.
 *
 * <p>For game disconnects, lifecycle code must pass at least the old nickname
 * in this command, and should pass the old listener when the connection exposes
 * one. The old session can be removed from the registry before the game worker
 * processes the command, so the game controller must not rely on the registry to
 * recover those old values.
 */
public class SystemDisconnectCommand implements QueuedCommand {
    private final String sessionId;
    private final String nickname;
    private final Listener listener;

    public SystemDisconnectCommand(String sessionId) {
        this(sessionId, null, null);
    }

    public SystemDisconnectCommand(String sessionId, String nickname, Listener listener) {
        this.sessionId = sessionId;
        this.nickname = nickname;
        this.listener = listener;
    }

    @Override
    public String getSessionId() {
        return this.sessionId;
    }

    public String getNickname() {
        return this.nickname;
    }

    public Listener getListener() {
        return this.listener;
    }
}
